style.css:
/* Jira Kanban Board Column Colors */
[data-testid="software-board.board-container.board.columns.column"]:nth-child(1) {
    background-color: #e8e8e8 !important; /* Grey for BACKLOG */
}

[data-testid="software-board.board-container.board.columns.column"]:nth-child(2) {
    background-color: #bbdefb !important; /* Blue for DONE */
}

[data-testid="software-board.board-container.board.columns.column"]:nth-child(3) {
    background-color: #fff3c4 !important; /* Yellow for IN PROGRESS */
}

[data-testid="software-board.board-container.board.columns.column"]:nth-child(4) {
    background-color: #e1bee7 !important; /* Purple for NEXT SPRINT */
}

/* Test rule to confirm it's working */
body { border: 2px solid red !important; }
